const $=s=>document.querySelector(s), euro=n=>new Intl.NumberFormat('tr-TR',{style:'currency',currency:'EUR',maximumFractionDigits:0}).format(n), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const profiles=[['Budget Saver','♧','Az harca, çok keşfet. Ekonomik seçenekler ve ücretsiz deneyimler.'],['Student Lifestyle','☕','Kampüsün ötesinde. Öğrenci indirimleri, kafeler ve yeni arkadaşlar.'],['Balanced Lifestyle','⚖','Biraz tasarruf, biraz konfor. Kendi dengeni bul.'],['Comfort Seeker','✦','Konforuna alan aç. Daha özel mekânlar ve rahat bir yaşam.']];
const cities={Milano:{country:'İtalya',rent:600,food:260,transit:22,fun:140,personal:80},Berlin:{country:'Almanya',rent:560,food:240,transit:30,fun:120,personal:75},Lizbon:{country:'Portekiz',rent:500,food:220,transit:30,fun:110,personal:70},Prag:{country:'Çekya',rent:420,food:190,transit:15,fun:95,personal:60}};
let state;try{state=JSON.parse(localStorage.getItem('budventure-v1'))}catch{}state={city:'Milano',months:4,budget:5500,profile:1,housing:'Paylaşımlı ev',expenses:[],reviews:[],...state};let step=0,selected=0,rating=5,receipt=null,query='Yerel bir yemek denemek istiyorum.',category='Yemek',maxPrice=35;const names=['Seyahatini planla','Planına göz at','Birlikte keşfedelim','Yerel öneriler','Deneyimini paylaş'];
function save(){localStorage.setItem('budventure-v1',JSON.stringify(state))}function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3200)}
function calc(){let c=cities[state.city],m=[.76,1,1.2,1.65][state.profile],rent=c.rent*({'Öğrenci yurdu':.8,'Paylaşımlı ev':1,'Özel daire':1.65}[state.housing]);let rows=[['Konaklama',rent],['Yeme içme',c.food*m],['Ulaşım',c.transit],['Sosyal yaşam',c.fun*m],['Kişisel harcamalar',c.personal*m]];let base=rows.reduce((a,r)=>a+r[1],0);rows.push(['Beklenmedik giderler',base*.1]);let monthly=base*1.1,total=monthly*state.months,spent=state.expenses.reduce((a,e)=>a+e.amount,0),daily=Math.max(0,(state.budget-rent*state.months-c.transit*state.months-base*.1*state.months-spent)/(state.months*30));return{rows,monthly,total,spent,daily,short:Math.max(0,total-state.budget)}}
function go(n){step=n;render();window.scrollTo({top:0,behavior:'smooth'})}function heading(k,title,desc){return `<div class="stepsline">${names.map((_,i)=>`<i class="${i<=step?'done':''}"></i>`).join('')}</div><div class="heading"><div class="eyebrow">${k}</div><h1>${title}</h1><p class="intro">${desc}</p></div>`}function actions(next,label){return `<div class="actions"><button class="secondary" onclick="go(${Math.max(0,step-1)})">← Geri</button><button class="primary" onclick="go(${next})">${label} →</button></div>`}
function render(){let c=calc();$('#breadcrumb').textContent=`${step<2?'SEYAHAT ÖNCESİ':'YENİ ŞEHRİNDE'} / ADIM 0${step+1}`;$('#nav').innerHTML=names.map((n,i)=>`<button class="${step===i?'active':''}" onclick="go(${i})"><span>${i<step?'✓':i+1}</span>${n}</button>`).join('');$('#app').innerHTML=[plan,overview,chat,discovery,review][step](c);bind()}
function plan(c){return heading('01 / Macera burada başlıyor','Yeni şehrin.<br><em>Senin yaşam tarzın.</em>','Nereye gideceğini anlat, bütçene uygun öğrenci hayatını birlikte planlayalım.')+`<div class="travelstamp"><b>✈</b>LESS WORRY<br>MORE ADVENTURE</div><div class="layout"><div><section class="panel"><h2 class="sectiontitle"><span>↗</span> Önce, yolculuğunu tanıyalım</h2><div class="fields"><label>Gideceğin ülke<select id="country">${['İtalya','Almanya','Portekiz','Çekya'].map(x=>`<option ${x===cities[state.city].country?'selected':''}>${x}</option>`).join('')}</select></label><label>Şehir<select id="city">${Object.keys(cities).map(x=>`<option ${x===state.city?'selected':''}>${x}</option>`).join('')}</select></label><label>Ne kadar kalacaksın?<select id="months">${[1,2,3,4,5,6,9,12].map(x=>`<option value="${x}" ${x==state.months?'selected':''}>${x} ay</option>`).join('')}</select></label><label>Toplam bütçen (€)<input id="budget" type="number" min="1" max="1000000" value="${state.budget}"><p class="hint">Bursun ve birikimlerin dahil, tüm seyahat için.</p></label><label style="grid-column:1/-1">Konaklama tercihin<select id="housing">${['Öğrenci yurdu','Paylaşımlı ev','Özel daire'].map(x=>`<option ${x===state.housing?'selected':''}>${x}</option>`).join('')}</select></label></div></section><section class="panel"><h2 class="sectiontitle"><span>♡</span> Hangi hayat sana daha yakın?</h2><p class="hint" style="margin:-12px 0 20px">Gelirin değil, önceliklerin. Dilediğin zaman değiştirebilirsin.</p><div class="profilegrid">${profiles.map((p,i)=>`<button class="profile ${state.profile===i?'selected':''}" onclick="chooseProfile(${i})"><span class="radio"></span><span class="icon">${p[1]}</span><b>${p[0]}</b><p>${p[2]}</p></button>`).join('')}</div></section><div class="actions"><small>✧ Planın sana özel.<br>Her adımda yeniden düzenleyebilirsin.</small><button class="primary" onclick="go(1)">Planımı oluştur ↗</button></div></div><div><section class="summary"><div class="eyebrow">YOLCULUĞUNA BİR BAKIŞ</div><h3>${state.city} seni bekliyor.</h3><p>Yeni sokaklar, yeni arkadaşlar.<br>Hesabı yapılmış bir başlangıç.</p><div class="ticket"><div><span>Rota</span><b>${cities[state.city].country} → ${state.city}</b></div><div><span>Süre</span><b>${state.months} ay · ${state.months*30} gün</b></div><div><span>Yaşam tarzın</span><b>${profiles[state.profile][0]}</b></div></div><small>AYLIK KULLANILABİLİR BÜTÇEN</small><div class="big">${euro(state.budget/state.months)} <span style="font-size:12px;font-weight:400">/ ay</span></div><div class="tag">Toplam ${euro(state.budget)} ile yola çıkıyorsun</div></section><div class="greenbox">✦ <b>Güzel bir başlangıç</b><br>Planında beklenmedik giderlere de yer ayırıyoruz. İçin rahat, rotan açık olsun.</div><p class="tiny">Planlama rakamları örnek tahminlerdir; canlı fiyat veya finansal tavsiye değildir.</p></div></div>`}
function chooseProfile(i){state.profile=i;save();render()}function bind(){['city','months','budget','housing'].forEach(k=>{let el=$('#'+k);if(el)el.onchange=()=>{let v=k==='months'||k==='budget'?Number(el.value):el.value;if((k==='budget'&&(!Number.isFinite(v)||v<=0||v>1000000))){toast('Lütfen 1–1.000.000 € arasında bir bütçe gir.');el.value=state.budget;return}state[k]=v;save();render()}});if($('#country'))$('#country').onchange=e=>{state.city=Object.keys(cities).find(k=>cities[k].country===e.target.value);save();render()}}
function overview(c){return heading('02 / Sana özel yol haritası',`${state.city} hayatının<br><em>ilk hesabı hazır.</em>`,`${profiles[state.profile][0]} · ${state.months} ay · ${state.housing}. Planın, tercihlerinle şekillendi.`)+`<div class="stats"><div class="stat"><small>TAHMİNİ TOPLAM</small><strong>${euro(c.total)}</strong><small>${state.months} aylık yaşam planı</small></div><div class="stat"><small>GÜNLÜK ESNEK BÜTÇEN</small><strong>${euro(c.daily)}</strong><small>Konaklama, ulaşım ve rezerv sonrası</small></div><div class="stat"><small>TOPLAM HARCAMAN</small><strong>${euro(c.spent)}</strong><small>${state.expenses.length} kayıtlı harcama</small></div></div><div class="layout"><section class="panel"><h2 class="sectiontitle">Bütçenin nereye gidiyor?</h2><small>Aylık tahmini dağılım</small>${c.rows.map((r,i)=>`<div class="barrow"><span>${r[0]}</span><b>${euro(r[1])}</b></div><div class="bar"><i style="width:${r[1]/c.monthly*100}%;background:${i%2?'#afd082':'#9881c8'}"></i></div>`).join('')}<div class="barrow"><b>Aylık toplam</b><b>${euro(c.monthly)}</b></div></section><div><div class="notice ${c.short?'warning':''}"><b>${c.short?'Biraz daha hazırlık iyi olabilir.':'Bütçende nefes alacak alan var.'}</b><br>${c.short?`Bu yaşam planı için yaklaşık ${euro(c.short)} daha biriktirmen gerekiyor. Yurt veya daha ekonomik bir profil seçerek planı azaltabilirsin.`:`Tahmini plana göre ${euro(state.budget-c.total)} payın kalıyor. Bir kısmını acil durumlar için koru.`}</div><div class="greenbox"><b>Şehre alışırken</b><br>Öğrenci ulaşım kartını araştır. İlk hafta market fiyatlarını karşılaştır. Ev sözleşmesinde depozito ve faturaları ayrıca kontrol et.</div><p class="tiny">Örnek maliyetlerdir. Uçuş, vize ve depozito bu yaşam tahminine dahil değildir.</p></div></div>${expenseForm()}${actions(2,'Şehri keşfet')}`}
function expenseForm(){return `<section class="panel"><h2 class="sectiontitle">Günlük harcamalarını takip et</h2><form onsubmit="addExpense(event)" class="fields"><label>Açıklama<input name="title" required maxlength="80" placeholder="Örn. market alışverişi"></label><label>Tutar (€)<input name="amount" required type="number" step="0.01" min="0.01" max="100000"></label><button class="secondary" type="submit">+ Harcama ekle</button></form>${state.expenses.slice(-4).reverse().map(e=>`<div class="expense"><span>${esc(e.title)}</span><b>${euro(e.amount)}</b></div>`).join('')}</section>`}function addExpense(e){e.preventDefault();let d=new FormData(e.target),a=Number(d.get('amount'));if(!Number.isFinite(a)||a<=0)return;state.expenses.push({title:String(d.get('title')),amount:a,date:new Date().toISOString()});save();render();toast(a>calc().daily?'Harcama eklendi. Günlük esnek bütçeni kontrol et.':'Harcama kaydedildi, kalan bütçen güncellendi.')}
function chat(c){let q=query.toLocaleLowerCase('tr'),type=/kahve|kafe/.test(q)?'Kafe':/aktivite|müze|park|gez/.test(q)?'Aktivite':'Yemek';category=type;return heading('03 / Sen söyle, birlikte bulalım','Bugün canın<br><em>ne yapmak istiyor?</em>','Bütçeni bilen bir yol arkadaşı. Şehrini kendi ritminde keşfet.')+`<div class="chat"><div class="notice">✦ ${state.city} · ${profiles[state.profile][0]} · Günlük esnek bütçe ${euro(c.daily)}</div><div class="bubble">${esc(query)}</div><div class="response"><div class="eyebrow">BUDVENTURE REHBERİN</div><h2 style="font:800 22px Manrope">${type==='Yemek'?'Şehri bir lokmayla tanıyalım.':type==='Kafe'?'Küçük bir kahve molası verelim.':'Yeni bir anıya yer açalım.'}</h2><p>${type==='Yemek'?`${state.city==='Milano'?'Milano’da risotto veya panzerotto ile başlayabilirsin.':'Yerel mutfağı keşfetmek için öğrenci menülerine göz atabilirsin.'} ${euro(Math.min(18,c.daily*.5))} civarında bir öğün hedeflemek bütçende günün kalanı için alan bırakır.`:type==='Kafe'?'Öğrenci dostu bir kahve molası için küçük, mahalle kafelerine göz at. Menüde oturma ve paket fiyatlarının farklı olabileceğini kontrol et.':'Ücretsiz parklar ve öğrenci indirimli kültür etkinlikleri iyi bir başlangıç. Ziyaret saatlerini ve rezervasyon koşullarını kontrol et.'}</p><p class="tiny">Bu MVP’de rehber, kategoriye göre hazırlanmış örnek yanıtlar sunar; canlı yapay zekâ veya arama bağlantısı yoktur.</p><button class="primary" onclick="go(3)">Bana uygun yerleri göster ↗</button></div><div class="chips">${['Yerel bir yemek denemek istiyorum.','Kahve içip ders çalışmak istiyorum.','Uygun fiyatlı bir aktivite arıyorum.'].map(q=>`<button onclick='ask(${JSON.stringify(q)})'>${q}</button>`).join('')}</div><form class="chatinput" onsubmit="event.preventDefault();ask(this.elements.request.value)"><input name="request" required maxlength="300" aria-label="Ne yapmak istiyorsun?" placeholder="Bugün aklında ne var?"><button class="primary">Gönder ↑</button></form></div>${actions(3,'Yerel önerilere geç')}`}
function ask(q){if(!q.trim())return;query=q.trim();render()}
function places(){let base=category==='Yemek'?[['Mahalle Mutfağı','🍝','Yerel yemekler · Öğrenci menüsü',12,4.7],['Kampüs Sofrası','🥗','Uygun fiyatlı öğle yemeği',8,4.6],['Sakin Masa','🍲','Rahat bir akşam yemeği',25,4.8]]:category==='Kafe'?[['Köşe Kahve','☕','Çalışma masası · Kahve',4,4.7],['Kampüs Kafe','🥐','Öğrenci molası',3,4.5],['Bahçe Kahvesi','🍵','Sakin bir bahçe',7,4.8]]:[['Şehir Parkı','🌳','Açık hava · Yürüyüş',0,4.8],['Küçük Galeri','🎨','Öğrenci bileti',6,4.6],['Film Akşamı','🎬','Bağımsız sinema',10,4.7]];return base.map((p,i)=>({name:p[0],icon:p[1],desc:p[2],price:p[3],score:p[4],id:i}))}
function discovery(c){return heading('04 / Şehrin küçük keşifleri',`Turist gibi değil,<br><em>kendin gibi yaşa.</em>`,`${state.city} için bütçene ve yaşam tarzına göre örnek yerel öneriler.`)+`<div class="notice">Tüm işletmeler, puanlar ve fiyatlar demo amaçlı kurgusaldır. Gerçek işletme veya doğrulanmış topluluk verisi değildir.</div><div class="filter"><label>Ne arıyorsun?<select onchange="category=this.value;render()">${['Yemek','Kafe','Aktivite'].map(x=>`<option ${category===x?'selected':''}>${x}</option>`).join('')}</select></label><label>En fazla (€)<input type="number" min="0" value="${maxPrice}" onchange="maxPrice=Math.max(0,Number(this.value));render()"></label><button class="secondary" onclick="maxPrice=Math.max(5,Math.floor(calc().daily/2));render()">Bütçeme uyarla</button></div><div class="cards">${places().filter(p=>p.price<=maxPrice).map(p=>`<article class="place"><div class="placeart">${p.icon}</div><div class="placebody"><span class="badge">${p.price<=c.daily*.5?'Bütçene uygun':'Özel bir mola'}</span><h3>${p.name}</h3><p>${p.desc}<br>${state.city} · Örnek işletme</p><div class="price"><span>${euro(p.price)} <small>tahmini kişi başı</small></span><span>★ ${p.score}<small>örnek puan</small></span></div><button class="${p.price<=c.daily*.5?'primary':'secondary'}" onclick="selectPlace(${p.id})">Burayı seç →</button></div></article>`).join('')||'<div class="panel">Bu fiyat aralığında öneri bulunamadı. Üst limiti artırabilirsin.</div>'}</div><p class="tiny">Bu demoda sponsorlu yerleştirme yoktur. İleride sponsorlu öneriler açıkça etiketlenir; yorum ve puanları etkilemez.</p>${actions(4,'Deneyimimi paylaş')}`}
function selectPlace(i){selected=i;receipt=null;go(4)}function review(c){let p=places()[selected]||places()[0];return heading('05 / Deneyimin başkasına yol olsun','Bir yorum.<br><em>Bir sonraki öğrenciye destek.</em>','Fiyatları birlikte görünür kılalım. Deneyimini paylaş, harcamanı planına ekle.')+`<div class="layout"><section class="panel"><span class="badge">${state.city} · Örnek işletme</span><h2>${p.icon} ${p.name}</h2><form onsubmit="submitReview(event)"><label>Deneyimin nasıldı?</label><div class="stars" role="group" aria-label="Puan seç">${[1,2,3,4,5].map(i=>`<button type="button" aria-label="${i} yıldız" aria-pressed="${i===rating}" class="${i<=rating?'on':''}" onclick="rating=${i};render()">★</button>`).join('')}</div><label>Diğer öğrencilere ne söylemek istersin?<textarea name="comment" required maxlength="1000" placeholder="Porsiyonlar, fiyatlar, ortam… Senin için nasıldı?"></textarea></label><div class="fields" style="margin:20px 0"><label>Ödediğin tutar (€)<input name="amount" type="number" required min="0" max="100000" step="0.01" value="${p.price}"></label><label>Ziyaret tarihi<input name="date" type="date" required value="${new Date().toLocaleDateString('en-CA',{timeZone:'Europe/Istanbul'})}"></label></div><label class="upload">↥ Fiş veya menü fotoğrafı ekle<small>İsteğe bağlı · JPG / PNG / WebP · En fazla 3 MB</small><input type="file" accept="image/jpeg,image/png,image/webp" onchange="loadReceipt(this)"><img id="receiptpreview" class="receiptpreview" alt="Seçilen fiş önizlemesi" ${receipt?`src="${receipt}"`:'hidden'}></label><p class="tiny">Fişteki kişisel bilgileri kapat. Fotoğraf bu oturumda önizlenir; sunucuya yüklenmez. Yorum ve harcama yalnızca bu tarayıcıda kaydedilir.</p><label style="margin:20px 0"><input type="checkbox" name="expense" checked style="width:auto;margin:0 7px 0 0">Bu tutarı harcamalarıma da ekle</label><button class="primary" type="submit">Deneyimimi kaydet ✓</button></form></section><div><div class="summary"><div class="eyebrow">KÜÇÜK KATKILAR, BÜYÜK FARK</div><h3>Birlikte daha iyi biliyoruz.</h3><p>Güncel bir fiyat, dürüst bir yorum. Senden sonra gelen öğrencinin hayatını kolaylaştırabilir.</p><div class="ticket"><div><span>Paylaşılan deneyimlerin</span><b>${state.reviews.length}</b></div><div><span>Kaydedilen harcama</span><b>${euro(c.spent)}</b></div></div><small>Katkıların bu cihazda saklanır.</small></div>${state.reviews.slice(-3).reverse().map(r=>`<div class="greenbox"><b>${esc(r.place)} · ${r.rating} ★</b><br>${esc(r.comment)}<br>${euro(r.amount)}</div>`).join('')}</div></div>${actions(1,'Bütçeme dön')}`}
function loadReceipt(input){let f=input.files[0];if(!f)return;if(f.size>3*1024*1024||!['image/jpeg','image/png','image/webp'].includes(f.type)){input.value='';toast('3 MB altında JPG, PNG veya WebP seç.');return}let reader=new FileReader();reader.onload=()=>{receipt=reader.result;$('#receiptpreview').src=receipt;$('#receiptpreview').hidden=false};reader.readAsDataURL(f)}
function submitReview(e){e.preventDefault();let d=new FormData(e.target),p=places()[selected]||places()[0],amount=Number(d.get('amount'));if(!Number.isFinite(amount)||amount<0)return;state.reviews.push({place:p.name,comment:String(d.get('comment')),rating,amount,date:d.get('date'),receiptAttached:!!receipt});if(d.get('expense')&&amount>0)state.expenses.push({title:p.name,amount,date:d.get('date')});save();receipt=null;render();toast('Deneyimin kaydedildi. Bütçen güncellendi. İyi ki paylaştın!')}
render();
